//! Gambatte dual-target tests (CGB-C-compatible).
//!
//! ROMs are tagged with their expected output per model: shared
//! `_dmg08_cgb04c_out<HEX>` (identical on both models) or model-split
//! `_dmg08_out<X>_cgb04c_out<Y>`; this crate checks the `cgb04c`
//! expectation. Audio tests use `outaudio0` (silent) / `outaudio1`
//! (audible) markers. ROMs come from c-sp/game-boy-test-roms v7.
//!
//! ROMs are shared with the missingno-gb crate (same test scenarios,
//! same expected outputs); loaded via `common::load_rom`.

use crate::common;

const TCYCLES: u32 = 1_053_360;

/// Frames the hex tests run before sampling the result. The reference samples
/// after the display settles in real time; a fixed T-cycle budget under-runs
/// double-speed tests (a DS frame is twice the T-cycles, and the KEY1-switch
/// blackouts further consume a cycle budget), so the hex runner counts frames.
/// 15 frames matches the prior `TCYCLES` (= 15 × 70224 dots) at single speed.
const FRAMES: u32 = 15;

fn extract_expected_hex(filename: &str) -> &str {
    let stem = filename
        .strip_suffix(".gbc")
        .or_else(|| filename.strip_suffix(".gb"))
        .unwrap_or(filename);
    let marker_pos = stem.rfind("_out").expect("no _out in filename");
    &stem[marker_pos + 4..]
}

fn check_screen(gbc: &missingno_gbc::GameBoyColor, rom_path: &str) {
    let screen = gbc.screen().to_greyscale_bytes();
    let filename = rom_path.rsplit('/').next().unwrap();
    let expected_hex = extract_expected_hex(filename);
    if !common::screen_matches_hex(&screen, expected_hex) {
        let shown = common::decode_screen_hex(&screen, expected_hex.len());
        panic!("Gambatte hex test {rom_path}: screen shows 0x{shown}, expected 0x{expected_hex}");
    }
}

/// Extract the CGB-expected audio outcome from a Gambatte test
/// filename. Both shared (`_dmg08_cgb04c_outaudioN`) and model-split
/// (`_dmg08_outaudioN_cgb04c_outaudioM`) ROMs end with the
/// `_cgb04c_outaudio` marker.
fn extract_expected_audio(filename: &str) -> bool {
    let marker = "_cgb04c_outaudio";
    let pos = filename
        .find(marker)
        .expect("no _cgb04c_outaudio marker in filename");
    filename.as_bytes()[pos + marker.len()] == b'1'
}

/// Gambatte audio test, matching gambatte's testrunner convention:
/// pass if the LAST FRAME's samples are all equal to the first sample
/// of that frame (`outaudio0`) or not all equal (`outaudio1`).
/// Transient audio earlier in the run is expected on hardware and
/// tolerated. Tolerance 0.005 accounts for APU DC-offset drift.
fn run_gambatte_audio_test(rom_path: &str) {
    let mut gbc = common::load_rom(rom_path);
    let _ = gbc.drain_audio_samples();
    common::run_for_tcycles(&mut gbc, TCYCLES);

    let samples = gbc.drain_audio_samples();
    let samples_per_frame = samples.len() / 15;
    let last_frame_start = samples.len().saturating_sub(samples_per_frame);
    let last_frame = &samples[last_frame_start..];
    let any_audio = if let Some(&(l0, r0)) = last_frame.first() {
        last_frame
            .iter()
            .any(|&(l, r)| (l - l0).abs() > 0.005 || (r - r0).abs() > 0.005)
    } else {
        false
    };

    let filename = rom_path.rsplit('/').next().unwrap();
    let expect_audio = extract_expected_audio(filename);
    assert_eq!(
        any_audio,
        expect_audio,
        "Gambatte audio test {rom_path}: expected audio={expect_audio}, got audio={any_audio} (samples={})",
        samples.len(),
    );
}

fn run_gambatte_hex_test(rom_path: &str) {
    let mut gbc = common::load_rom(rom_path);
    common::run_frames(&mut gbc, FRAMES);
    check_screen(&gbc, rom_path);
}

fn run_gambatte_hex_test_cgb(rom_path: &str) {
    let mut gbc = common::load_cgb_rom(rom_path);
    common::run_frames(&mut gbc, FRAMES);
    check_screen(&gbc, rom_path);
}

/// Capture an execution trace for the ROM named by `MOREPORK_CAPTURE_ROM`
/// (relative to the gbc roms dir). Requires the `morepork` feature and
/// `MOREPORK_PROFILE`; writes to `receipts/traces/`. Not a pass/fail test.
#[cfg(feature = "morepork")]
#[test]
#[ignore = "manual capture harness; run with --ignored and MOREPORK_CAPTURE_ROM set"]
fn morepork_capture() {
    let rom = std::env::var("MOREPORK_CAPTURE_ROM")
        .expect("set MOREPORK_CAPTURE_ROM to a ROM path relative to the gbc roms dir");
    let mut run = common::load_cgb_rom_traced(&rom);
    common::run_for_tcycles(&mut run, TCYCLES);
    run.finish();
}

macro_rules! gambatte_audio_test {
    ($name:ident, $path:literal) => {
        #[test]
        fn $name() {
            run_gambatte_audio_test($path);
        }
    };
}

macro_rules! gambatte_hex_test {
    ($name:ident, $path:literal) => {
        #[test]
        fn $name() {
            run_gambatte_hex_test($path);
        }
    };
}

macro_rules! gambatte_hex_test_cgb {
    ($name:ident, $path:literal) => {
        #[test]
        fn $name() {
            run_gambatte_hex_test_cgb($path);
        }
    };
}

